components.css:
.ds-nav{box-sizing:border-box;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));padding:10px max(12px,env(safe-area-inset-right,0px)) calc(10px + env(safe-area-inset-bottom,0px)) max(12px,env(safe-area-inset-left,0px));border-top:1px solid var(--wns-line, #343939);background:var(--wns-navigation-bg, #111413);font-family:'Manrope Variable', sans-serif}
.ds-nav a{min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;padding-inline:4px;min-height:58px;border-radius:13px;text-align:center;text-decoration:none;color:var(--wns-navigation-muted, #9ca7a0);font-size:.6875rem;line-height:1.55}
.ds-nav a[aria-current=page]{background:var(--wns-surface-raised, #222626);color:var(--wns-mint, #b8f3d4)}

.ds-nav svg{width:23px;height:23px;color:var(--wns-text, #f5f5f0);opacity:.7}
.ds-nav a[aria-current=page] svg{opacity:1}
.ds-nav span{white-space:nowrap;line-height:1.45}
.ds-nav a:focus-visible{outline:3px solid var(--wns-mint, #b8f3d4);outline-offset:4px}
@media(min-width:768px){.ds-nav{width:100%;max-width:36rem;margin:0 auto 16px;gap:8px;padding:8px;border:1px solid var(--wns-line, #343939);border-radius:22px}.ds-nav a{font-size:.8125rem}}
.ds-nav a{position:relative}.ds-nav a[aria-current=page]::after{content:"";position:absolute;inset-block-start:0;width:20px;height:2px;border-radius:2px;background:var(--wns-mint, #b8f3d4)}@media(hover:hover){.ds-nav a:not([aria-current=page]):hover{background:var(--wns-surface, #191b1b);color:var(--wns-text, #f5f5f0)}}@media(prefers-reduced-motion:no-preference){.ds-nav a{transition:color 160ms ease,background-color 160ms ease}}
